    function CompleteDeadScout(player)
        GiveExpForPlayer(100, player)
        GiveGoldForPlayer(150, player)
        RemoveJournalEntry(player, "deadscout_quest_journal")
        SendQuestMessageForPlayer(QUEST_DONE_STRING .. GetLocalString("Посмертный Рапорт", "Deadly Report"), bj_TEXT_DELAY_QUESTDONE, player)
        PlayQuestCompletedSound(player-1)
        DelayAction(GetRandomReal(100., 660.), function() EnableCallQuest(player) end)
    end


    function SpawnDeadScoutQuest()
        local scout = CreateNPC("n03B", gg_rct_dead_scout_spawn, 300., GetLocalString("Разведчик", "Scout"))

            SetUnitOwner(scout, Player(8), false)
            ScoutData = GetUnitData(scout)
            ScoutData.questmarker = AddQuestMark(scout, MARK_TYPE_EXCLAMATION, MARK_COMMON)
            BlzPlaySpecialEffect(ScoutData.questmarker, ANIM_TYPE_STAND)
            local triggered = { [1] = false, [2] = false, [3] = false, [4] = false, [5] = false, [6] = false }
            local trg = CreateTrigger()
            TriggerRegisterUnitInRange(trg, scout, 1000., nil)
            TriggerAddAction(trg, function()
                if IsAHero(GetTriggerUnit()) then
                    local unit = GetTriggerUnit()

                        if not triggered[GetPlayerId(GetOwningPlayer(unit)) + 1] then
                            triggered[GetPlayerId(GetOwningPlayer(unit)) + 1] = true
                            SetUnitAnimation(scout, "Death")
                            DelayAction(3.034, function()
                                if GetLocalPlayer() == GetOwningPlayer(unit) then SetUnitTimeScale(scout, 0) end
                            end)
                            for i = 1, 6 do
                                if not triggered[i] then
                                    return
                                end
                            end
                            DestroyTrigger(trg)
                            triggered = nil
                        end

                end
            end)

            AddInteractiveOption(scout, {
            name = GetLocalString("Очнись", "Wake up"),
            id = "dead_scout_start_conv",
            feedback = function(clicked, clicking, player)

                    PlayConversation("dead_scout_start_conv", scout, player)
                    LockInteractiveOptionIdPlayer(scout, "dead_scout_start_conv", player)
                    AddJournalEntry(player, "deadscout_quest_journal", "UI\\BTNOrderHunterIcon.blp", GetLocalString("Посмертный Рапорт", "Deadly Report"), 5, false)
                    AddJournalEntryText(player, "deadscout_quest_journal", GetConversationText("dead_scout_start_conv", scout, player), false)
                    AddJournalEntryObjective(player, "deadscout_quest_journal", "deadscout_quest_journal_obj", GetLocalString("Найти в замке кому рассказать о разведчике", "Find the one in the castle who I can talk about a scout"))
                    SendQuestMessageForPlayer(QUEST_REVEALED_STRING .. GetLocalString("Посмертный Рапорт", "Deadly Report"), bj_TEXT_DELAY_QUEST, player)

                    if GetLocalPlayer() == Player(player - 1) then
                        BlzPlaySpecialEffect(ScoutData.questmarker, ANIM_TYPE_DEATH)
                        StartSound(QUEST_REVEALED_SOUND or bj_questDiscoveredSound)
                    end

                    UnlockInteractiveOptionIdPlayer(gg_unit_n029_0022, "anar_dead_scout_done", player)

                end }, 1)

    end


